import pandas as pd

def find_valid_products(orders: pd.DataFrame) -> pd.DataFrame:
    if orders.empty:
        return pd.DataFrame({'product_id': []})
    orders['yr'] = pd.to_datetime(orders['purchase_date']).dt.year
    grp = orders.groupby(['product_id', 'yr']).size().reset_index(name='cnt')
    valid = grp[grp['cnt'] >= 3]
    merged = pd.merge(valid, valid, on='product_id', suffixes=('_1', '_2'))
    res = merged[merged['yr_2'] == merged['yr_1'] + 1]['product_id'].drop_duplicates()
    return pd.DataFrame({'product_id': res})
